//! Simulation state, generated from the shipped PDB.
//!
//! GENERATED by `re/scripts/gen_sim_state.py` from `schema/pdb-types.json` and
//! `schema/state-schema.json`. Do not edit by hand; re-run the generator.
//!
//! Every offset, size and C type here is the MSVC-emitted layout for
//! `riseofnations.exe` sha256 `30478a44..625079` -- [measured], not reconstructed.
//! `walked` marks a field whose bytes the class's `walk_data` visits, which is
//! exactly the lockstep/save-game critical set: `CheckSum`, `SaveGame` and
//! `LoadGame` are the only implementations of the `DataWalk` visitor.
//!
//! Storage is one allocation per width, sliced into planes. A scalar field owns
//! one plane and reads back as a contiguous slice over rows. An array field owns
//! `count` planes laid out row-major, so one row's array is contiguous instead.

#![allow(dead_code)]
#![allow(non_snake_case)]
#![allow(clippy::identity_op)]

/// How a PDB field is stored here.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Repr {
    I32, U32, I16, U16, I8, U8, F32,
    /// A container, pointer or `String`: recorded so the coverage report counts
    /// its bytes, deliberately not materialised.
    Aggregate,
    /// A scalar array too large to allocate per world (see MAX_ARRAY_ELEMS).
    Deferred,
    /// A bitfield packed into a neighbouring storage unit.
    Bitfield,
}

impl Repr {
    /// Whether this field has real columns behind it.
    pub fn materialised(self) -> bool {
        !matches!(self, Repr::Aggregate | Repr::Deferred | Repr::Bitfield)
    }
}

/// Which width pool a materialised field lives in.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Pool { W4, W2, W1, WF, None }

/// One field of one class, exactly as the compiler laid it out.
#[derive(Clone, Copy, Debug)]
pub struct FieldDesc {
    pub name: &'static str,
    /// Byte offset inside the class, including base subobjects.
    pub offset: u32,
    /// Byte size of the whole field (an array counts every element).
    pub size: u32,
    /// The C++ type spelled as the PDB spells it.
    pub ctype: &'static str,
    /// Which class in the inheritance chain declared it.
    pub declared_in: &'static str,
    pub repr: Repr,
    /// Element count: 1 for a scalar, N for `T[N]`, 0 for an aggregate.
    pub count: u32,
    /// `Some(true)` if `walk_data` visits every byte, `Some(false)` if it visits
    /// none or only part, `None` if no walker was recovered for this class.
    pub walked: Option<bool>,
    /// Non-null when this field shares storage with an earlier one (an anonymous
    /// union member).
    pub alias_of: Option<&'static str>,
    /// Which width pool holds it.
    pub pool: Pool,
    /// Plane index inside that pool. An array field owns `count` consecutive
    /// planes' worth of space, laid out row-major.
    pub plane: u32,
}

/// One byte range that a class's `walk_data` visits, in program order.
#[derive(Clone, Copy, Debug)]
pub struct WalkOp {
    pub begin: u32,
    pub end: u32,
    /// Conditional forward jumps spanning the op. An over-approximation -- see
    /// the caveats in `schema/state-schema.json`.
    pub guard_depth: u32,
    pub in_loop: bool,
}

/// A whole class: its true `sizeof`, its fields, and its walker.
#[derive(Clone, Copy, Debug)]
pub struct ClassDesc {
    pub name: &'static str,
    pub sizeof: u32,
    pub fields: &'static [FieldDesc],
    /// The class whose `walk_data` defines the sim-critical byte set.
    pub walk_class: Option<&'static str>,
    /// VA of that `walk_data`, for anyone re-checking against the binary.
    pub walk_va: Option<&'static str>,
    pub walk_ops: &'static [WalkOp],
}

impl ClassDesc {
    pub fn field(&self, name: &str) -> Option<&'static FieldDesc> {
        self.fields.iter().find(|f| f.name == name)
    }
    /// (materialised fields, total fields, materialised bytes, sizeof).
    pub fn coverage(&self) -> (usize, usize, u32, u32) {
        let mut nf = 0usize;
        let mut nb = 0u32;
        for f in self.fields {
            if f.alias_of.is_some() { continue; }
            if f.repr.materialised() { nf += 1; nb += f.size; }
        }
        let total = self.fields.iter().filter(|f| f.alias_of.is_none()).count();
        (nf, total, nb, self.sizeof)
    }
    /// Bytes this class's `walk_data` visits that we do materialise.
    pub fn walked_materialised_bytes(&self) -> u32 {
        self.fields.iter()
            .filter(|f| f.alias_of.is_none() && f.repr.materialised() && f.walked == Some(true))
            .map(|f| f.size).sum()
    }
}

