        #[inline] pub fn is_empty(&self) -> bool { self.len == 0 }
        #[inline] pub fn capacity(&self) -> usize { self.cap }
        /// Bytes of column storage reserved, whatever the population.
        pub fn bytes_reserved(&self) -> usize {
            self.cap * (W4_PLANES * 4 + W2_PLANES * 2 + W1_PLANES + WF_PLANES * 4)
        }
        /// Append a zeroed row. Returns its index, or `None` at capacity.
        pub fn push_zeroed(&mut self) -> Option<usize> {
            if self.len >= self.cap { return None; }
            let row = self.len;
            self.len += 1;
            self.zero_row(row);
            Some(row)
        }
        pub fn zero_row(&mut self, row: usize) {
            for p in 0..W4_PLANES { self.w4[p * self.cap + row] = 0; }
            for p in 0..W2_PLANES { self.w2[p * self.cap + row] = 0; }
            for p in 0..W1_PLANES { self.w1[p * self.cap + row] = 0; }
            for p in 0..WF_PLANES { self.wf[p * self.cap + row] = 0.0; }
        }
        /// Copy every column of `src` over `dst`. This is the swap half of a
        /// swap-remove, so it must touch every plane -- a missed one is a field
        /// that silently survives a despawn.
        pub fn copy_row(&mut self, dst: usize, src: usize) {
            if dst == src { return; }
            let cap = self.cap;
            for p in 0..W4_PLANES { self.w4[p * cap + dst] = self.w4[p * cap + src]; }
            for p in 0..W2_PLANES { self.w2[p * cap + dst] = self.w2[p * cap + src]; }
            for p in 0..W1_PLANES { self.w1[p * cap + dst] = self.w1[p * cap + src]; }
            for p in 0..WF_PLANES { self.wf[p * cap + dst] = self.wf[p * cap + src]; }
        }
